import{_ as n,l,o as e,c as i,v as t,p as s,x as r,d,i as h,S as E}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"回购流","description":"","frontmatter":{"title":"回购流","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/buyback-flows.md","filePath":"quant/buyback-flows.md","lastUpdated":1789023840000}'),p={name:"quant/buyback-flows.md"};function c(u,a,A,_,m,b){const o=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="回购流" tabindex="-1">回购流 <a class="header-anchor" href="#回购流" aria-label="Permalink to &quot;回购流&quot;">​</a></h1><div class="epigraph"><p>公司按授权在市场上买回本股票，是又一股可预测的机械需求；截面上的「回购异象」混着估值、动量与实施缺口，不能直接当免费因子。</p><footer>—— Ikenberry, Lakonishok and Vermaelen, Journal of Finance, 1995；实施与后绩效应见后续回购文献</footer></div><p><a href="/quant/index-inclusion-passive-flow">上一课</a>是指数规则驱动的被动买盘。回购流的缺口是<strong>发行人自己作为流动性需求方</strong>：授权公告、实际买入、注销。公司金融里回购的动机与信号在金融栏，本课不重写。量化栏要问的是可交易流：谁在什么价成交、如何进入组合与因子。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Ikenberry–Lakonishok–Vermaelen 记录授权后的长期超额，常被读成市场低估。后续工作把授权与实际买入分开：真正产生价格压力的是执行，不是新闻稿。问题是识别三层：(1) 公告日事件；(2) 执行窗口的隐蔽买盘（往往用 10b-18 一类规则摊开）；(3) 股份减少对每股与因子暴露的会计效应。用公告日做事件研究会高估可捕获收益；用财报里的「本期回购金额」当下一期信号，有滞后也有前瞻偏差。</p><p>与被动流：指数基金必须在生效日完成；回购可以择时、可以暂停。流的可预测性更弱，但方向偏买入、偏在「公司认为便宜」的区间，于是和价值因子纠缠。不要再用 <a href="/quant/capm">CAPM</a> 把回购组合的 alpha 当新发现——先对价值、动量、质量中性。</p><h3 id="授权不是成交" tabindex="-1">授权不是成交 <a class="header-anchor" href="#授权不是成交" aria-label="Permalink to &quot;授权不是成交&quot;">​</a></h3><p>许多授权从未用满。策略若买「有授权」的名字，买到的是期权：公司可以买、可以不买。可交易信号应尽量靠近实际执行（后续公告、追踪、流通变化），并承认报告滞后。</p><p><span class="marginnote">回购在指数再平衡前也能改变权重：流通市值下降会强制被动卖出或减少买入。被动流与回购流在调仓周可以反向对冲，归因时要拆开。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>信号：授权事件、执行强度、净发行（回购减增发）。对冲：价值、动量、低波动。执行：不要假设与公司同步隐蔽成交。容量：大盘回购深、小盘授权水分大。税务与交易规则因市场而异，中国与美国不可同一回测。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>发行人买盘向上倾斜需求的一侧，短期提供价格支撑，长期改变股份与杠杆。若市场对执行反应不足，留下漂移；若执行已被算法抢跑，只剩公告噪声。拥挤的「回购因子」ETF 会把执行信息更快打进价格，生命周期与后课相同。</p>',13)),(e(),s(E,null,{default:r(()=>[h(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20Auth%5B%22%E6%8E%88%E6%9D%83%E5%85%AC%E5%91%8A%22%5D%20--%3E%20Opt%5B%22%E6%9C%AA%E5%BF%85%E6%89%A7%E8%A1%8C%22%5D%0A%20%20Exec%5B%22%E5%AE%9E%E9%99%85%E4%B9%B0%E5%85%A5%22%5D%20--%3E%20Press%5B%22%E6%9C%BA%E6%A2%B0%E4%B9%B0%E7%9B%98%22%5D%0A%20%20Exec%20--%3E%20Acct%5B%22%E8%82%A1%E4%BB%BD%E4%B8%8E%E5%9B%A0%E5%AD%90%E6%9A%B4%E9%9C%B2%22%5D%0A%20%20Press%20--%3E%20Xs%5B%22%E4%B8%AD%E6%80%A7%E5%90%8E%E6%98%AF%E5%90%A6%E8%BF%98%E5%89%A9%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写如何配合未公开回购计划交易。内部人窗口与 10b5-1 是合规对象，不是 alpha 来源。金融栏的回购理论此处只引用，不重推。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>可交易的是执行流，不是授权新闻稿。</li><li>先对价值/动量中性，再谈回购异象。</li><li>与指数被动流在调仓周可能对冲，归因要拆。</li><li>出处：Ikenberry, Lakonishok and Vermaelen, <em>JF</em>, 1995；公司金融动机见金融栏回购课。</li></ul>',4))])}const k=n(p,[["render",c]]);export{B as __pageData,k as default};
